import fs from 'node:fs';
const idx=fs.readFileSync('releases/nova-otp-delivery-20261031/deploy/clientes/index.mjs','utf8');
const form=fs.readFileSync('releases/nova-otp-delivery-20261031/deploy/clientes/form.html','utf8');
const m=idx.match(/var pilot_form_default = (".*?");\n/s);
if(!m){console.log('NOT_FOUND');process.exit(1);}
const embedded=JSON.parse(m[1]);
console.log('MATCH:',embedded===form, 'lenEmbedded:',embedded.length,'lenForm:',form.length);

import fs from 'node:fs';
const idx=fs.readFileSync(new URL('./deploy/clientes/index.mjs',import.meta.url),'utf8');
const form=fs.readFileSync(new URL('./deploy/clientes/form.html',import.meta.url),'utf8');
const m=idx.match(/var pilot_form_default = (".*?");\n/s);
if(!m){console.log('NOT_FOUND');process.exit(1);}
const embedded=JSON.parse(m[1]);
console.log('MATCH:',embedded===form, 'lenEmbedded:',embedded.length,'lenForm:',form.length);
